(() => {
'use strict';
const el=id=>document.getElementById(id);
const regionNames={domestic:'국내',overseas:'해외'};
const kindNames={news:'기사',report:'보고서',announcement:'공지·발표',event:'행사',data:'통계·데이터',link:'참고 링크'};
const storageKey='korfin-dashboard-v1:'+location.pathname.replace(/[^/]*$/,'');
const state={catalog:{councils:[],categories:[]},resources:[],sources:[],editorial:{schema_version:1,overrides:{},manual_resources:[]},draft:{overrides:{},manual_resources:[]},saved:[],council:'all',category:'all',region:'all',search:'',sort:'newest',savedOnly:false,interestsOnly:false,limit:20,editing:false,current:null,adding:false};
let toastTimer;
const label=id=>state.catalog.councils.find(c=>c.id===id)?.short||id;
const categoryLabel=id=>state.catalog.categories.find(c=>c.id===id)?.label||'자료';
function toast(message){el('toast').textContent=message;el('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el('toast').hidden=true},4500)}
function store(){localStorage.setItem(storageKey,JSON.stringify({draft:state.draft,saved:state.saved}))}
function validURL(value){const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('http 또는 https 자료 주소를 입력해 주세요.');u.hash='';for(const key of [...u.searchParams.keys()])if(key.toLowerCase().startsWith('utm_')||['fbclid','gclid'].includes(key.toLowerCase()))u.searchParams.delete(key);u.searchParams.sort();return u.href}
async function resourceID(url){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(validURL(url)));return [...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,24)}
function cleanOverride(value){if(!value||typeof value!=='object'||Array.isArray(value))return {};const clean={};
 if(Array.isArray(value.tags))clean.tags=[...new Set(value.tags.filter(t=>state.catalog.councils.some(c=>c.id===t)))];
 for(const [key,choices]of [['region',Object.keys(regionNames)],['category',state.catalog.categories.map(c=>c.id)],['kind',Object.keys(kindNames)]])if(choices.includes(value[key]))clean[key]=value[key];
 for(const [key,max]of [['title',250],['summary',1000]])if(typeof value[key]==='string')clean[key]=value[key].trim().slice(0,max);
 if(typeof value.hidden==='boolean')clean.hidden=value.hidden;return clean;
}
function cleanEditorial(value){if(!value||typeof value!=='object'||!Array.isArray(value.manual_resources)||!value.overrides||typeof value.overrides!=='object')throw Error('편집 파일 형식이 올바르지 않습니다.');
 const result={schema_version:1,overrides:{},manual_resources:[]};
 for(const [id,override]of Object.entries(value.overrides)){if(/^[a-f0-9]{24}$/.test(id))result.overrides[id]=cleanOverride(override)}
 for(const row of value.manual_resources.slice(0,500)){try{if(typeof row.title!=='string'||!row.title.trim())continue;const url=validURL(row.url);result.manual_resources.push({...cleanOverride(row),id:/^[a-f0-9]{24}$/.test(row.id)?row.id:undefined,url,title:row.title.trim().slice(0,250),source:String(row.source||'직접 등록').slice(0,80),published_at:row.published_at||null,collected_at:row.collected_at||new Date().toISOString(),tag_method:'manual',auto_tags:[]})}catch{}}
 return result;
}
function applyOverride(resource,override){const clean=cleanOverride(override);return {...resource,...clean,tag_method:Object.hasOwn(clean,'tags')?'manual':resource.tag_method}}
function effectiveResources(){const map=new Map(state.resources.map(r=>[r.id,{...r}]));for(const row of window.Community?.resources||[])if(!map.has(row.id))map.set(row.id,{...row});for(const row of state.draft.manual_resources)map.set(row.id,{...row,hidden:false});return [...map.values()].map(row=>applyOverride(row,state.draft.overrides[row.id])).filter(row=>!row.hidden)}
function filteredResources(resources=effectiveResources()){return resources.filter(row=>(state.council==='all'||row.tags?.includes(state.council))&&(state.category==='all'||row.category===state.category)&&(state.region==='all'||row.region===state.region)&&(!state.interestsOnly||(row.tags||[]).some(id=>window.Community?.interests.includes(id)))&&(!state.savedOnly||state.saved.includes(row.id))&&(!state.search||(row.title+' '+row.source+' '+(row.summary||'')+' '+(row.tags||[]).map(label).join(' ')).toLowerCase().includes(state.search))).sort((a,b)=>{if(state.sort==='source')return a.source.localeCompare(b.source,'ko');const order=(a.published_at||a.collected_at||'').localeCompare(b.published_at||b.collected_at||'');return state.sort==='oldest'?order:-order})}
function localDate(value){if(!value)return '발행일 미제공';const d=new Date(value);return Number.isNaN(d.valueOf())?'발행일 미확인':d.toLocaleDateString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit'})}
function button(text,callback,className=''){const b=document.createElement('button');b.type='button';b.textContent=text;b.className=className;b.onclick=callback;return b}
function navigate(page){const name=['resources','market','reports'].includes(page)?page:'market';el('resource-sidebar').hidden=name!=='resources';el('workspace').dataset.page=name;for(const p of ['resources','market','reports'])el(p+'-view').hidden=p!==name;for(const a of document.querySelectorAll('[data-page]'))a.classList.toggle('active',a.dataset.page===name);if(location.hash!=='#'+name)history.replaceState(null,'','#'+name)}
function chooseCouncil(id){state.council=id;state.savedOnly=false;state.interestsOnly=false;state.limit=20;navigate('resources');render()}
function renderSidebar(resources){el('council-nav').replaceChildren();for(const council of state.catalog.councils){const b=button('',()=>chooseCouncil(council.id),'side-btn'+(state.council===council.id&&!state.savedOnly?' active':''));b.title=council.label;const name=document.createElement('span');name.textContent=council.short;const n=document.createElement('b');n.textContent=resources.filter(r=>r.tags?.includes(council.id)).length;b.append(name,n);el('council-nav').append(b)}el('all-resources').classList.toggle('active',state.council==='all'&&!state.savedOnly&&!state.interestsOnly);el('saved-resources').classList.toggle('active',state.savedOnly);el('all-count').textContent=resources.length;el('saved-count').textContent=resources.filter(r=>state.saved.includes(r.id)).length}
function renderFilters(){el('region-filters').replaceChildren();for(const [id,name]of [['all','전체'],['domestic','국내'],['overseas','해외']]){const b=button(name,()=>{state.region=id;state.limit=20;render()},id===state.region?'active':'');b.setAttribute('aria-pressed',String(id===state.region));el('region-filters').append(b)}el('category-filters').replaceChildren();for(const c of [{id:'all',label:'전체 주제'},...state.catalog.categories]){const b=button(c.label,()=>{state.category=c.id;state.limit=20;render()},c.id===state.category?'active':'');b.setAttribute('aria-pressed',String(c.id===state.category));el('category-filters').append(b)}}
function toggleSaved(id){const old=state.saved;state.saved=old.includes(id)?old.filter(x=>x!==id):[...old,id];try{store();render()}catch{state.saved=old;toast('저장 공간을 사용할 수 없습니다. 브라우저 설정을 확인해 주세요.')}}
function resourceCard(row){const card=document.createElement('article');card.className='resource-card';const icon=document.createElement('div');icon.className='resource-icon';icon.textContent={news:'N',report:'R',announcement:'!',data:'#',event:'E',link:'↗'}[row.kind]||'N';
 const body=document.createElement('div');body.className='resource-body';const meta=document.createElement('div');meta.className='resource-meta';const origin=document.createElement('span');origin.className='origin '+row.region;origin.textContent=regionNames[row.region]||'기타';const info=document.createElement('span');info.textContent=row.source+' · '+localDate(row.published_at)+' · '+categoryLabel(row.category)+' · '+(kindNames[row.kind]||'자료');meta.append(origin,info);
 const h=document.createElement('h3'),link=document.createElement('a');link.href=validURL(row.url);link.target='_blank';link.rel='noopener';link.textContent=row.title+' ↗';h.append(link);body.append(meta,h);
 if(row.summary){const summary=document.createElement('p');summary.className='resource-summary';summary.textContent=row.summary;body.append(summary)}
 const tags=document.createElement('div');tags.className='resource-tags';for(const id of row.tags||[])tags.append(button(label(id),()=>chooseCouncil(id)));if(!row.tags?.length){const tag=document.createElement('span');tag.className='manual-tag';tag.textContent='공통·참고 자료';tags.append(tag)}if(row.tag_method==='manual'){const t=document.createElement('span');t.className='manual-tag';t.textContent='직접 편집';tags.append(t)}body.append(tags);
 const actions=document.createElement('div');actions.className='resource-actions';const saved=state.saved.includes(row.id);const save=button(saved?'★':'☆',()=>toggleSaved(row.id),saved?'saved':'');save.setAttribute('aria-label',saved?'저장 해제':'자료 저장');save.setAttribute('aria-pressed',String(saved));actions.append(save);if(state.editing)actions.append(button('편집',()=>openEditor(row),'edit-item'));window.Community?.decorateCard(body,row);card.append(icon,body,actions);return card;
}
function render(){const resources=effectiveResources();renderSidebar(resources);renderFilters();const rows=filteredResources(resources);el('total-stat').textContent=resources.length.toLocaleString();el('domestic-stat').textContent=resources.filter(r=>r.region==='domestic').length.toLocaleString();el('overseas-stat').textContent=resources.filter(r=>r.region==='overseas').length.toLocaleString();el('view-title').textContent=state.savedOnly?'다시 보고 싶은 자료.':state.council==='all'?'흩어진 정보를, 한곳에.':state.catalog.councils.find(c=>c.id===state.council)?.label||'자료 모아보기';el('view-description').textContent=state.savedOnly?'이 브라우저에서 저장한 자료를 모아볼 수 있습니다.':'국내외 뉴스와 연구자료를 협의회별로 모아보세요.';el('result-count').textContent=rows.length+'건';el('list-title').firstChild.textContent=state.savedOnly?'저장한 자료 ':'최신 자료 ';el('resource-list').replaceChildren();for(const row of rows.slice(0,state.limit)){try{el('resource-list').append(resourceCard(row))}catch{}}
 el('resource-empty').hidden=rows.length!==0;el('load-more').hidden=rows.length<=state.limit;el('edit-banner').hidden=!state.editing;el('editor-toggle').classList.toggle('active',state.editing);el('editor-toggle').setAttribute('aria-pressed',String(state.editing));const count=Object.keys(state.draft.overrides).length+state.draft.manual_resources.length;el('draft-count').textContent=count?'이 브라우저의 미공개 편집 '+count+'건':'';window.Community?.afterRender();
}
function showTags(tags){el('edit-tags').replaceChildren();for(const c of state.catalog.councils){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=c.id;box.checked=tags.includes(c.id);label.append(box,document.createTextNode(c.label));el('edit-tags').append(label)}}
function openEditor(resource){state.current=resource;state.adding=!resource;const r=resource||{title:'',url:'',source:'',summary:'',region:'domestic',category:'industry',kind:'link',tags:state.council==='all'?[]:[state.council]};el('editor-title').textContent=resource?'자료 태그·분류 편집':'자료 등록';for(const field of ['title','url','source','summary','region','category','kind'])el('edit-'+field).value=r[field]||'';el('edit-url').readOnly=!!resource;el('edit-source').readOnly=!!resource;showTags(r.tags||[]);el('editor-error').textContent='';el('reset-tags').hidden=!resource;window.Community?.editorOpened(resource);el('editor-dialog').showModal()}
function mergeEditorial(){const overrides={...state.editorial.overrides,...state.draft.overrides};const manuals=new Map();for(const r of [...state.editorial.manual_resources,...state.draft.manual_resources])manuals.set(r.id||r.url,r);return {schema_version:1,overrides,manual_resources:[...manuals.values()]}}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderSources(){el('sources-list').replaceChildren();for(const s of state.sources){const row=document.createElement('div');row.className='source-row';const text=document.createElement('div');text.textContent=s.name;const last=document.createElement('small');last.textContent='최근 성공 '+(s.last_success?new Date(s.last_success).toLocaleString('ko-KR'):'없음');text.append(last);const status=document.createElement('span');status.textContent={ok:'수집 완료',cached:'이전 자료 유지',error:'수집 대기'}[s.status]+' · '+s.count+'건';if(s.status!=='ok')status.className='warning';row.append(text,status);el('sources-list').append(row)}}
async function load(){el('resource-error').textContent='자료를 불러오는 중입니다.';try{const [catalog,bundle,editorial]=await Promise.all(['catalog','resources','editorial'].map(async name=>{const r=await fetch('data/'+name+'.json',{cache:'no-store'});if(!r.ok)throw Error('자료 파일 없음');return r.json()}));state.catalog=catalog;state.resources=(bundle.resources||[]).filter(r=>{try{validURL(r.url);return /^[a-f0-9]{24}$/.test(r.id)}catch{return false}});state.sources=bundle.sources||[];state.editorial=cleanEditorial(editorial);try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved){state.draft=cleanEditorial({schema_version:1,...saved.draft});state.saved=Array.isArray(saved.saved)?saved.saved.filter(id=>/^[a-f0-9]{24}$/.test(id)):[]}}catch{toast('이 브라우저의 저장 내용을 읽지 못했습니다. 공개 자료를 표시합니다.')}
 el('edit-category').replaceChildren();for(const c of catalog.categories){const o=document.createElement('option');o.value=c.id;o.textContent=c.label;el('edit-category').append(o)}el('collection-time').textContent=new Date(bundle.updated_at).toLocaleString('ko-KR');el('resource-error').textContent='';render();renderSources();}catch{el('resource-error').textContent='자료 목록을 불러오지 못했습니다. 자동 배포의 자료 수집 작업이 완료됐는지 확인해 주세요.'}}
// Storage adapter: replace store/load/export with authenticated shared writes when a backend is connected.
// AI belongs in scripts/tagging.py or a trusted server; it must not bypass human overrides.
el('all-resources').onclick=()=>{state.council='all';state.savedOnly=false;state.interestsOnly=false;state.limit=20;navigate('resources');render()};
el('saved-resources').onclick=()=>{state.savedOnly=true;state.interestsOnly=false;state.council='all';state.limit=20;navigate('resources');render()};
el('resource-search').oninput=e=>{state.search=e.target.value.trim().toLowerCase();state.limit=20;render()};
el('resource-sort').onchange=e=>{state.sort=e.target.value;render()};
el('load-more').onclick=()=>{state.limit+=20;render()};
el('clear-filters').onclick=()=>{state.council='all';state.category='all';state.region='all';state.savedOnly=false;state.interestsOnly=false;state.search='';el('resource-search').value='';state.limit=20;render()};
el('editor-toggle').onclick=()=>{state.editing=!state.editing;render()};
el('add-resource').onclick=()=>window.Community?window.Community.beginAdd():openEditor(null);el('close-editor').onclick=()=>el('editor-dialog').close();
el('reset-tags').onclick=()=>showTags(state.current?.auto_tags||[]);
el('editor-form').onsubmit=async event=>{event.preventDefault();const previous=state.draft;el('editor-save').disabled=true;try{const fields={title:el('edit-title').value.trim(),summary:el('edit-summary').value.trim(),region:el('edit-region').value,category:el('edit-category').value,kind:el('edit-kind').value,tags:[...el('edit-tags').querySelectorAll('input:checked')].map(box=>box.value)};if(!fields.title)throw Error('제목을 입력해 주세요.');if(window.Community?.connected&&(state.adding||state.current?.community&&state.current.owner_id===window.Community.user?.id)){await window.Community.saveResource(fields,state.adding?null:state.current);el('editor-dialog').close();return}if(state.adding){const url=validURL(el('edit-url').value.trim()),id=await resourceID(url);const duplicate=effectiveResources().find(r=>r.id===id||r.url===url);if(duplicate)throw Error('이미 등록된 자료입니다. 기존 자료를 편집해 주세요.');const row={...cleanOverride(fields),id,url,source:el('edit-source').value.trim().slice(0,80)||'직접 등록',published_at:null,collected_at:new Date().toISOString(),tag_method:'manual',auto_tags:[]};state.draft={...previous,manual_resources:[...previous.manual_resources,row]};}else state.draft={...previous,overrides:{...previous.overrides,[state.current.id]:cleanOverride(fields)}};store();render();el('editor-dialog').close();toast('이 브라우저에 저장했습니다. 전체 공개 반영은 편집 파일 내보내기를 이용하세요.');}catch(error){state.draft=previous;el('editor-error').textContent=error.message||'저장하지 못했습니다.'}finally{el('editor-save').disabled=false}};
el('export-edits').onclick=()=>{download('editorial.json',mergeEditorial());toast('내려받은 파일을 GitHub의 config/editorial.json에 덮어쓰면 전체에 반영됩니다.')};
el('import-edits').onclick=()=>el('import-file').click();el('import-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;const previous=state.draft;try{if(file.size>3_000_000)throw Error('편집 파일이 너무 큽니다.');const data=cleanEditorial(JSON.parse(await file.text()));state.draft=data;store();render();toast('편집 파일을 이 브라우저에 불러왔습니다.')}catch(error){state.draft=previous;toast(error.message||'편집 파일을 읽지 못했습니다.')}event.target.value=''};
el('source-status').onclick=()=>el('sources-dialog').showModal();el('close-sources').onclick=()=>el('sources-dialog').close();el('resources-refresh').onclick=load;
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1));load();
window.DashboardCore={state,filteredResources,effectiveResources,cleanEditorial,applyOverride,mergeEditorial,render,load,resourceID,openEditor,cleanOverride,validURL,toast};
})();
